import { summarize, sourceUrl } from './requirements.mjs';

const md = (s) => s.replaceAll('|', '\\|').replaceAll('\n', ' ');
export function renderSummary(catalogue, assessments, matrix, sources) {
  const summary = summarize(catalogue, assessments, matrix);
  const lines = [
    '# Standards inventory summary',
    '',
    '<!-- Generated by npm run requirements:docs; edit standards/assessments.json for assessments. -->',
    '',
    'This index covers SysML 2.0 Part 1 and KerML 1.0. It is a source inventory with',
    'bounded evidence mappings. It is not a completed atomic-requirements review or a',
    'conformance claim. Read [the method and remaining work](requirements.md), or use',
    '[the searchable inventory](requirements.html).',
    '',
    '| Indexed source unit | SysML | KerML |',
    '| --- | ---: | ---: |',
  ];
  for (const kind of [
    'clause',
    'unnumbered-heading',
    'grammar-production',
    'metaclass',
    'property',
    'constraint',
    'operation',
    'parameter',
    'association',
    'generalization',
    'enumeration',
    'enumeration-literal',
    'package',
    'package-import',
    'prose-candidate',
    'normative-artifact',
    'library-model',
    'archive-metadata',
    'schema-definition',
  ]) {
    const count = (s) => catalogue.items.filter((i) => i.standard === s && i.kind === kind).length;
    lines.push(`| ${kind} | ${count('sysml')} | ${count('kerml')} |`);
  }
  lines.push(
    '',
    `${summary.sourceUnits} indexed units overlap. Do not sum them into a requirements denominator.`,
    'All clause/prose decomposition remains pending. No percentage is published.',
    '',
    '## Evidence mapped so far',
    '',
    `${summary.assessments} bounded assessments map ${summary.executableCases} executable cases and ${summary.plannedCases} planned cases.`,
    'Linked tests are evidence for the assessment wording only. They do not qualify',
    'a whole source clause, its descendants, or a named constraint merely because it',
    'belongs to the same metaclass. Product robustness cases are identified separately.',
    '',
    '| Assessment | Category | Implementation / API | Positive / negative / robustness / planned | Limits |',
    '| --- | --- | --- | --- | --- |',
  );
  for (const a of assessments.assessments) {
    const tests = a.tests.map((t) => matrix.cases.find((c) => c.id === t.case));
    const count = (p) => tests.filter((c) => !c.planned && c.polarity === p).length;
    lines.push(
      `| ${a.id} | ${a.category} | ${a.implementation.status} / ${a.api.status} | ${count('positive')} / ${count('negative')} / ${count('robustness')} / ${tests.filter((c) => c.planned).length} | ${md(a.limits)} |`,
    );
  }
  lines.push(
    '',
    '## Sources and extraction checks',
    '',
    'All numbered clauses reconcile between PDF bookmarks, the printed TOC and body',
    'headings. The importer checks pinned source bytes and reports counts for every',
    'indexed XMI type. Five printed grammar headers omit an equals sign; these have',
    'explicit extraction exceptions and are included. Prose candidates locate modal',
    'passages by digest; they are not automatically classified as normative obligations.',
    '',
  );
  for (const source of Object.values(sources.sources))
    lines.push(
      `- [${source.standard} ${source.document}](${source.url}), SHA-256 \`${source.sha256}\`.`,
    );
  lines.push(
    '',
    'The complete catalogue, source hashes and reviewed mappings are in `standards/`.',
    'No PDF prose, OCL bodies or original source PDFs are redistributed in this index.',
    '',
  );
  return lines.join('\n');
}

export function renderBrowser(catalogue, assessments, matrix, sources) {
  const summary = summarize(catalogue, assessments, matrix);
  // The browser carries identifiers/locators and mappings, not original normative
  // text. Escape '<' so upstream names can never terminate this data script.
  const data = JSON.stringify({
    items: catalogue.items.map((i) => ({
      id: i.id,
      title: i.title,
      kind: i.kind,
      facet: i.facet,
      standard: i.standard,
      section: i.section,
      page: i.page ?? i.pdfPage,
      url: sourceUrl(i, sources),
      note: i.extractionNote,
    })),
    assessments: assessments.assessments,
    cases: matrix.cases.map((c) => ({
      id: c.id,
      polarity: c.polarity,
      planned: Boolean(c.planned),
    })),
    evidence: assessments.evidence,
  }).replaceAll('<', '\\u003c');
  return `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>SysML · Standards inventory</title>
<style>
*{box-sizing:border-box}body{margin:0;background:#f3f5f5;color:#172b30;font:15px/1.5 system-ui,-apple-system,sans-serif}
header{background:#163c43;color:white;padding:30px 5vw}header p{max-width:950px;color:#d7e6e8;margin:8px 0}h1{font-size:30px;margin:0}h2{font-size:19px;margin:0 0 12px;overflow-wrap:anywhere}.eyebrow{text-transform:uppercase;font-size:11px;letter-spacing:.16em;color:#abd8d0}
main{padding:24px 5vw;max-width:1700px;margin:auto}.stats{display:flex;gap:25px;flex-wrap:wrap;font-size:14px;margin-top:22px}.stats strong{font-size:22px;margin-right:5px}
.notice{background:#fff8e8;border-left:4px solid #b47719;padding:12px 16px;margin-bottom:20px;max-width:1100px}
.controls{display:flex;gap:10px;flex-wrap:wrap;align-items:end;margin-bottom:18px}label{display:flex;flex-direction:column;font-size:12px;font-weight:600;gap:4px}input,select,button{font:inherit;padding:9px 12px;border:1px solid #b5c9cc;border-radius:5px;background:white;color:#172b30}input{width:330px}button{cursor:pointer}button:hover,button:focus{background:#e4efee}a{color:#076c72}header a{color:#bfe3dc}
.layout{display:grid;grid-template-columns:minmax(0,1.65fr) minmax(330px,1fr);gap:20px;align-items:start}.panel{min-width:0;background:white;border:1px solid #d1dedf;border-radius:8px;padding:20px}#detail{position:sticky;top:18px;max-height:calc(100vh - 40px);overflow:auto}table{width:100%;border-collapse:collapse}th{text-align:left;color:#5d7378;font-size:12px;border-bottom:2px solid #dbe4e5;padding:8px}td{padding:11px 8px;border-bottom:1px solid #edf1f2;vertical-align:top;font-size:13px}.row-button{padding:0;border:0;border-radius:0;background:none;text-align:left;color:#086a70;font-weight:600;word-break:break-word}.id{font:11px ui-monospace,monospace;color:#697b80;overflow-wrap:anywhere;margin-top:3px}.tag{display:inline-block;background:#edf3f3;border-radius:4px;padding:2px 6px;font-size:11px}.muted{color:#63797e;font-size:13px}.pagination{display:flex;justify-content:space-between;align-items:center;margin-top:14px}.detail-block{border-top:1px solid #e1e8e8;margin-top:16px;padding-top:16px}li{margin-bottom:7px}ul{padding-left:20px}.status{font-weight:600;color:#8a6118}.summary-link{display:inline-block;margin-top:10px}#detail p{overflow-wrap:anywhere}
@media(max-width:1000px){.layout{grid-template-columns:1fr}#detail{position:static;max-height:none}input{width:min(80vw,330px)}main{padding:18px}header{padding:24px}}
</style></head><body>
<header><div class="eyebrow">SysML Viewer / Engineering evidence</div><h1>Standards inventory</h1>
<p>SysML 2.0 Part 1 + KerML 1.0 · Pinned normative source index and bounded implementation evidence.</p>
<div class="stats"><span><strong>${summary.clauses.toLocaleString('en-US')}</strong>clauses</span><span><strong>${summary.grammarProductions}</strong>productions</span><span><strong>${summary.metamodelConstraints}</strong>constraints</span><span><strong>${summary.assessments}</strong>assessments</span></div>
<a class="summary-link" href="requirements.md">Method, scope and next review steps</a></header>
<main><div class="notice"><strong>Coverage percentage: not established.</strong> Clause and prose decomposition remains pending. An indexed rule or a linked passing case does not mean a complete language feature is qualified.</div>
<div class="controls"><label>Browse<select id="mode"><option value="sources">Source inventory</option><option value="assessments">Bounded assessments</option></select></label>
<label>Search<input id="search" type="search" placeholder="Name, clause, rule or assessment ID"></label>
<label>Standard<select id="standard"><option value="">Both standards</option><option value="sysml">SysML</option><option value="kerml">KerML</option></select></label>
<label>Facet<select id="facet"><option value="">All facets</option></select></label>
<label>Kind<select id="kind"><option value="">All source units</option></select></label>
<label>Evidence<select id="mapped"><option value="">All units</option><option value="yes">Mapped assessments</option><option value="no">Unassessed units</option></select></label></div>
<div class="layout"><section class="panel"><p class="muted" id="count" aria-live="polite"></p><table><thead><tr><th>Source unit / obligation</th><th>Classification</th><th>Evidence</th></tr></thead><tbody id="rows"></tbody></table>
<div class="pagination"><button id="previous">Previous</button><span class="muted" id="page"></span><button id="next">Next</button></div></section>
<aside id="detail" class="panel" aria-live="polite"><h2>Inspect an entry</h2><p>Select a source unit or assessment to see exact source links, implementation evidence, linked tests and remaining limits.</p><p class="muted">Unmapped means unassessed. It does not prove that the upstream engine lacks an implementation.</p></aside></div></main>
<script id="inventory" type="application/json">${data}</script>
<script>
const data=JSON.parse(document.getElementById('inventory').textContent);
const el=(id)=>document.getElementById(id), byId=new Map(data.items.map(i=>[i.id,i]));
const related=new Map();for(const a of data.assessments)for(const id of a.sources){if(!related.has(id))related.set(id,[]);related.get(id).push(a);}
const cases=new Map(data.cases.map(c=>[c.id,c]));let page=0,filtered=[];const size=60;
const node=(tag,text,className)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(className)n.className=className;return n;};
for(const field of ['facet','kind'])for(const value of [...new Set(data.items.map(i=>i[field]))].sort()){const o=node('option',value);o.value=value;el(field).append(o);}
function link(text,url){const a=node('a',text);a.href=url;return a;}
function detailItem(i){const panel=el('detail');panel.replaceChildren(node('h2',i.title),node('p',i.id,'id'),node('p',i.standard.toUpperCase()+' · §'+i.section+' · '+i.kind,'muted'),link('Open pinned normative source',i.url));if(i.note)panel.append(node('p',i.note));const matches=related.get(i.id)||[];panel.append(node('p',matches.length?'Bounded evidence is mapped below. The whole source unit remains unqualified.':'Implementation: unassessed. Public API: unassessed. Tests: unmapped.','status'));for(const a of matches)appendAssessment(panel,a);}
function appendAssessment(panel,a){const block=node('section',undefined,'detail-block');block.append(node('h2',a.id),node('p',a.obligation),node('p',a.category+' · '+a.applicability+' · '+a.priority,'muted'),node('p','Implementation: '+a.implementation.status+' · API: '+a.api.status,'status'),node('p',a.limits));const sources=node('ul');for(const id of a.sources){const i=byId.get(id);const li=node('li');li.append(link(i.standard.toUpperCase()+' §'+i.section+' — '+i.title,i.url));sources.append(li);}block.append(node('strong','Source anchors'),sources);const tests=node('ul');for(const t of a.tests){const c=cases.get(t.case);tests.append(node('li',t.case+' · '+(c.planned?'planned; not executed':c.polarity+'; mapped assertions: '+t.checks.join(', '))));}if(!a.tests.length)tests.append(node('li','No mapped tests.'));block.append(node('strong','Test evidence'),tests);const evidence=node('ul');for(const id of new Set([...a.implementation.evidence,...a.api.evidence])){const e=data.evidence[id];const li=node('li');li.append(link(e.path,'../'+e.path),node('div',e.symbol+' · '+e.role,'muted'));evidence.append(li);}block.append(node('strong','Reviewed implementation locations'),evidence);panel.append(block);}
function render(){const mode=el('mode').value,q=el('search').value.toLowerCase().trim(),standard=el('standard').value,facet=el('facet').value,kind=el('kind').value,mapped=el('mapped').value;el('kind').disabled=mode!=='sources';el('mapped').disabled=mode!=='sources';filtered=(mode==='sources'?data.items:data.assessments).filter(i=>{const units=mode==='sources'?[i]:i.sources.map(id=>byId.get(id));return (!q||JSON.stringify(i).toLowerCase().includes(q))&&(!standard||units.some(u=>u.standard===standard))&&(!facet||units.some(u=>u.facet===facet))&&(mode!=='sources'||((!kind||i.kind===kind)&&(!mapped||(related.has(i.id)===(mapped==='yes')))));});page=Math.max(0,Math.min(page,Math.ceil(filtered.length/size)-1));el('rows').replaceChildren();for(const i of filtered.slice(page*size,(page+1)*size)){const row=node('tr'),name=node('td'),button=node('button',i.title||i.obligation,'row-button');button.onclick=()=>{if(mode==='sources')detailItem(i);else{el('detail').replaceChildren();appendAssessment(el('detail'),i);}};name.append(button,node('div',i.id,'id'));const category=node('td',mode==='sources'?i.standard.toUpperCase()+' · §'+i.section:i.category);category.append(node('div',mode==='sources'?i.kind:i.applicability,'muted'));const evidence=node('td',mode==='sources'?(related.has(i.id)?'Bounded mapping':'Unassessed'):i.implementation.status+' / '+i.api.status);row.append(name,category,evidence);el('rows').append(row);}el('count').textContent=filtered.length.toLocaleString()+' matching '+(mode==='sources'?'source units':'assessments');el('page').textContent='Page '+(page+1)+' of '+Math.max(1,Math.ceil(filtered.length/size));el('previous').disabled=page===0;el('next').disabled=(page+1)*size>=filtered.length;}
for(const id of ['mode','search','standard','facet','kind','mapped'])el(id).addEventListener('input',()=>{page=0;render();});el('previous').onclick=()=>{page--;render();};el('next').onclick=()=>{page++;render();};render();
</script></body></html>\n`;
}
